:root {
    --bg-primary: #1a1a1a;
    --bg-secondary: #2d2d2d;
    --text-primary: #e0e0e0;
    --text-secondary: #b0b0b0;
    --accent: #6366f1;
    --accent-hover: #818cf8;
    --accent-focus: #a5b4fc;
    --border: #404040;
    --error: #ef4444;
    --success: #10b981;
}

@media (prefers-color-scheme: light) {
    :root {
        --bg-primary: #ffffff;
        --bg-secondary: #f5f5f5;
        --text-primary: #1a1a1a;
        --text-secondary: #666666;
        --accent: #6366f1;
        --accent-hover: #4f46e5;
        --accent-focus: #4338ca;
        --border: #e0e0e0;
        --error: #dc2626;
        --success: #059669;
    }
}

html {
    font-size: 16px;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    background-color: var(--bg-primary);
    color: var(--text-primary);
    line-height: 1.6;
    min-height: 100vh;
    padding: 2rem 1rem;
}

/* Skip to main content link */
.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background-color: var(--accent);
    color: white;
    padding: 0.5rem 1rem;
    text-decoration: none;
    border-radius: 0 0 4px 0;
    z-index: 100;
    font-weight: 600;
}

.skip-link:focus {
    top: 0;
}

/* Main layout */
main {
    max-width: 600px;
    margin: 0 auto;
}

h1 {
    font-size: 2rem;
    font-weight: 700;
    margin-bottom: 2rem;
    color: var(--text-primary);
}

/* Container */
.container {
    background-color: var(--bg-secondary);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 2rem;
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.2);
}

/* Form structure */
form {
    display: flex;
    flex-direction: column;
    gap: 2rem;
}

/* Form field wrapper */
.form-field {
    display: flex;
    flex-direction: column;
}

/* Fieldset and legend */
fieldset {
    border: none;
    margin: 0;
    padding: 0;
}

legend {
    font-size: 1.125rem;
    font-weight: 600;
    margin-bottom: 1.5rem;
    color: var(--text-primary);
    display: block;
    width: 100%;
    padding: 0;
}

/* Radio options container */
.radio-option {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    margin-bottom: 1.25rem;
    padding: 1rem;
    border-radius: 6px;
    border: 1px solid transparent;
    transition: all 0.2s ease;
}

.radio-option:hover {
    background-color: rgba(99, 102, 241, 0.08);
    border-color: var(--border);
}

/* Radio input styling */
input[type="radio"] {
    appearance: none;
    width: 20px;
    height: 20px;
    border: 2px solid var(--text-secondary);
    border-radius: 50%;
    cursor: pointer;
    transition: all 0.2s ease;
    flex-shrink: 0;
    background-color: var(--bg-primary);
}

input[type="radio"]:hover {
    border-color: var(--accent);
}

input[type="radio"]:focus {
    outline: none;
    border-color: var(--accent-focus);
    box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.1);
}

input[type="radio"]:checked {
    border-color: var(--accent);
    background-color: var(--accent);
    box-shadow: inset 0 0 0 4px var(--bg-secondary);
}

input[type="radio"]:checked:focus {
    box-shadow: 
        inset 0 0 0 4px var(--bg-secondary),
        0 0 0 3px rgba(99, 102, 241, 0.2);
}

input[type="radio"]:disabled {
    cursor: not-allowed;
    opacity: 0.5;
    border-color: var(--text-secondary);
}

/* Radio labels */
label {
    font-size: 1rem;
    color: var(--text-primary);
    cursor: pointer;
    user-select: none;
    font-weight: 500;
}

input[type="radio"]:disabled ~ label {
    cursor: not-allowed;
    opacity: 0.6;
}

/* Submit button */
.submit-btn {
    background-color: var(--accent);
    color: white;
    border: none;
    padding: 0.75rem 2rem;
    font-size: 1rem;
    font-weight: 600;
    border-radius: 6px;
    cursor: pointer;
    transition: all 0.2s ease;
    align-self: flex-start;
    min-height: 44px;
}

.submit-btn:hover:not(:disabled) {
    background-color: var(--accent-hover);
    box-shadow: 0 4px 12px rgba(99, 102, 241, 0.3);
}

.submit-btn:focus {
    outline: none;
    box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.2);
}

.submit-btn:active:not(:disabled) {
    background-color: var(--accent-focus);
    transform: translateY(1px);
}

.submit-btn:disabled {
    cursor: not-allowed;
    opacity: 0.6;
}

/* Forced colors mode support */
@media (forced-colors: active) {
    input[type="radio"] {
        border: 2px solid CanvasText;
        forced-color-adjust: none;
    }

    input[type="radio"]:checked {
        background-color: CanvasText;
    }

    .submit-btn {
        forced-color-adjust: none;
        border: 2px solid ButtonText;
    }

    .container {
        border-color: CanvasText;
    }
}

/* Reduced motion support */
@media (prefers-reduced-motion: reduce) {
    * {
        animation: none !important;
        transition: none !important;
    }
}

/* Responsive design */
@media (max-width: 640px) {
    body {
        padding: 1rem;
    }

    h1 {
        font-size: 1.5rem;
        margin-bottom: 1.5rem;
    }

    .container {
        padding: 1.5rem;
    }

    form {
        gap: 1.5rem;
    }

    legend {
        margin-bottom: 1rem;
        font-size: 1rem;
    }

    .radio-option {
        margin-bottom: 1rem;
        padding: 0.75rem;
    }

    .submit-btn {
        width: 100%;
        align-self: stretch;
    }
}
